+/// Every move crossing the clamp's mid-plane x = 0 within its length.
+fn crossings(t: &Toolpath) -> Vec<&Move> {
+    t.moves
+        .iter()
+        .filter(|m| {
+            let (a, b) = (m.from, m.to);
+            if a.x.min(b.x) > 0.0 || a.x.max(b.x) < 0.0 || a.x == b.x {
+                return false;
+            }
+            let y = a.y + (b.y - a.y) * (0.0 - a.x) / (b.x - a.x);
+            (8.0..=72.0).contains(&y)
+        })
+        .collect()
+}
